CREATE TABLE delivery_migration_locks (environment_id uuid PRIMARY KEY REFERENCES environments(id), run_id uuid NOT NULL REFERENCES execution_runs(id), preparation_id uuid NOT NULL REFERENCES delivery_preparations(id), migration_class text NOT NULL CHECK(migration_class IN ('compatible','reversible','destructive')), migration_hash text NOT NULL CHECK(migration_hash ~ '^[a-f0-9]{64}$'), fence integer NOT NULL CHECK(fence > 0), state text NOT NULL CHECK(state IN ('held','uncertain','released')), updated_at timestamptz NOT NULL);
CREATE TABLE delivery_migration_approvals (plan_id uuid PRIMARY KEY REFERENCES execution_plans(id), preparation_id uuid NOT NULL REFERENCES delivery_preparations(id), migration_hash text NOT NULL CHECK(migration_hash ~ '^[a-f0-9]{64}$'), approved_at timestamptz NOT NULL);
CREATE TABLE delivery_usage (run_id uuid PRIMARY KEY REFERENCES execution_runs(id), project_id uuid NOT NULL REFERENCES projects(id), environment_id uuid NOT NULL REFERENCES environments(id), intent text NOT NULL CHECK(intent IN ('build','release','rollback','cleanup')), cpu_milli_seconds bigint NOT NULL CHECK(cpu_milli_seconds >= 0), peak_memory_mib integer NOT NULL CHECK(peak_memory_mib >= 0), disk_mib bigint NOT NULL CHECK(disk_mib >= 0), duration_ms bigint NOT NULL CHECK(duration_ms >= 0), recorded_at timestamptz NOT NULL);
